import{_ as d,c as r,o as a,ah as e}from"./chunks/framework.DYJPYqf_.js";const b=JSON.parse('{"title":"🚀 IntelliJ IDEA 常用快捷键大全（Windows/Linux & macOS 对照）","description":"","frontmatter":{},"headers":[],"relativePath":"idea/keyMap.md","filePath":"idea/keyMap.md","lastUpdated":1787117657000}'),l={name:"idea/keyMap.md"};function h(i,t,n,o,s,m){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="🚀-intellij-idea-常用快捷键大全-windows-linux-macos-对照" tabindex="-1">🚀 IntelliJ IDEA 常用快捷键大全（Windows/Linux &amp; macOS 对照） <a class="header-anchor" href="#🚀-intellij-idea-常用快捷键大全-windows-linux-macos-对照" aria-label="Permalink to “🚀 IntelliJ IDEA 常用快捷键大全（Windows/Linux &amp; macOS 对照）”">​</a></h1><p>在日常开发中，熟练掌握快捷键能显著提升效率，减少鼠标操作。本文整理了 IntelliJ IDEA 常用快捷键，以表格形式呈现，涵盖 <strong>搜索、编辑、导航、重构、调试、项目窗口</strong>等常见场景，方便速查与学习。</p><hr><h2 id="🔍-全局搜索与查找" tabindex="-1">🔍 全局搜索与查找 <a class="header-anchor" href="#🔍-全局搜索与查找" aria-label="Permalink to “🔍 全局搜索与查找”">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>搜索一切</td><td>双击 Shift</td><td>双击 Shift</td></tr><tr><td>查找类</td><td>Ctrl + N</td><td>Cmd + O</td></tr><tr><td>查找文件</td><td>Ctrl + Shift + N</td><td>Cmd + Shift + O</td></tr><tr><td>查找符号</td><td>Ctrl + Alt + Shift + N</td><td>Cmd + Option + O</td></tr><tr><td>查找操作</td><td>Ctrl + Shift + A</td><td>Cmd + Shift + A</td></tr></tbody></table><hr><h2 id="🚀-代码编辑" tabindex="-1">🚀 代码编辑 <a class="header-anchor" href="#🚀-代码编辑" aria-label="Permalink to “🚀 代码编辑”">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>完成当前语句</td><td>Ctrl + Shift + Enter</td><td>Cmd + Shift + Enter</td></tr><tr><td>格式化代码</td><td>Ctrl + Alt + L</td><td>Cmd + Alt + L</td></tr><tr><td>复制当前行</td><td>Ctrl + D</td><td>Cmd + D</td></tr><tr><td>删除当前行</td><td>Ctrl + Y</td><td>Cmd + Backspace</td></tr><tr><td>上下移动行</td><td>Alt + Shift + ↑/↓</td><td>Alt + Shift + ↑/↓</td></tr><tr><td>扩展/缩小选择范围</td><td>Ctrl + W / Ctrl + Shift + W</td><td>Alt + ↑ / Alt + ↓</td></tr><tr><td>注释/取消注释</td><td>Ctrl + / / Ctrl + Shift + /</td><td>Cmd + / / Cmd + Shift + /</td></tr></tbody></table><hr><h2 id="🧭-导航跳转" tabindex="-1">🧭 导航跳转 <a class="header-anchor" href="#🧭-导航跳转" aria-label="Permalink to “🧭 导航跳转”">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>转到声明处</td><td>Ctrl + B</td><td>Cmd + B</td></tr><tr><td>转到实现处</td><td>Ctrl + Alt + B</td><td>Cmd + Alt + B</td></tr><tr><td>最近打开文件</td><td>Ctrl + E</td><td>Cmd + E</td></tr><tr><td>最近编辑位置</td><td>Ctrl + Shift + E</td><td>Cmd + Shift + E</td></tr><tr><td>错误间跳转</td><td>F2 / Shift + F2</td><td>F2 / Shift + F2</td></tr><tr><td>后退/前进导航</td><td>Ctrl + Alt + ←/→</td><td>Cmd + Alt + ←/→</td></tr></tbody></table><hr><h2 id="🛠️-重构代码" tabindex="-1">🛠️ 重构代码 <a class="header-anchor" href="#🛠️-重构代码" aria-label="Permalink to “🛠️ 重构代码”">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>显示重构菜单</td><td>Ctrl + Alt + Shift + T</td><td>Ctrl + T</td></tr><tr><td>重命名</td><td>Shift + F6</td><td>Shift + F6</td></tr><tr><td>提取方法</td><td>Ctrl + Alt + M</td><td>Cmd + Alt + M</td></tr><tr><td>提取变量</td><td>Ctrl + Alt + V</td><td>Cmd + Alt + V</td></tr><tr><td>内联</td><td>Ctrl + Alt + N</td><td>Cmd + Alt + N</td></tr><tr><td>安全删除</td><td>Alt + Delete</td><td>Cmd + Delete</td></tr></tbody></table><hr><h2 id="🐞-调试" tabindex="-1">🐞 调试 <a class="header-anchor" href="#🐞-调试" aria-label="Permalink to “🐞 调试”">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>单步进入</td><td>F7</td><td>F7</td></tr><tr><td>单步跳过</td><td>F8</td><td>F8</td></tr><tr><td>恢复运行</td><td>F9</td><td>Cmd + Option + R</td></tr></tbody></table><hr><h2 id="📁-项目窗口" tabindex="-1">📁 项目窗口 <a class="header-anchor" href="#📁-项目窗口" aria-label="Permalink to “📁 项目窗口”">​</a></h2><table tabindex="0"><thead><tr><th>功能描述</th><th>Windows/Linux</th><th>macOS</th></tr></thead><tbody><tr><td>打开/隐藏 Project 面板</td><td>Alt + 1</td><td>Cmd + 1</td></tr><tr><td>打开/隐藏 Console 控制台</td><td>Alt + 4</td><td>Cmd + 4</td></tr><tr><td>打开类结构</td><td>Alt + 7</td><td>Cmd + 7</td></tr></tbody></table><hr><h2 id="📌-总结" tabindex="-1">📌 总结 <a class="header-anchor" href="#📌-总结" aria-label="Permalink to “📌 总结”">​</a></h2><ul><li>IDEA 的快捷键可以在 <strong>File → Settings → Keymap</strong> 中自定义。</li><li>建议开发者逐步养成使用快捷键的习惯，尤其是 <strong>搜索、编辑、导航</strong> 三大类，能显著提升效率。</li><li>如果你在写博客或做笔记，可以将这些表格直接嵌入，作为速查手册。</li></ul>',23)])])}const c=d(l,[["render",h]]);export{b as __pageData,c as default};
